'use strict';

// MODULES //

var isnan = require( '@stdlib/math/base/assert/is-nan' );
var dlassq = require( '@stdlib/lapack/base/dlassq' ).ndarray;
var Float64Array = require( '@stdlib/array/float64' );
var min = require( '@stdlib/math/base/special/min' );
var abs = require( '@stdlib/math/base/special/abs' );
var sqrt = require( '@stdlib/math/base/special/sqrt' );


// MAIN //

/**
* Returns the value of the one norm, or the frobenius norm, or the infinity norm, or the element with the largest absolute value of a real matrix `A`.
*
* ## Notes
*
* -   use `norm` = `M`, to calculate the element with the largest absolute value
* -   use `norm` = `O`, to calculate the one norm
* -   use `norm` = `I`, to calculate the infinity norm
* -   use `norm` = `F`, to calculate the frobenius norm
*
* @private
* @param {string} norm - specifies the type of norm to be calculated
* @param {Float64Array} M - number of rows in `A`
* @param {Float64Array} N - number of columns in `A`
* @param {Float64Array} A - input array
* @param {Float64Array} strideA1 - stride of the first dimension of `A`
* @param {Float64Array} strideA2 - stride of the second dimension of `A`
* @param {Float64Array} offsetA - starting index of `A`
* @param {Float64Array} work - only used to compute the infinity norm, expects `M` indexed elements if computing the infinity norm otherwise it's fine to pass a dummy array
* @param {Float64Array} strideWork - stride length of `work`
* @param {Float64Array} offsetWork - starting index of `work`
* @returns {number} required norm value
*
* @example
* var Float64Array = require( '@stdlib/array/float64' );
*
* var A = new Float64Array( [ 1.0, 4.0, 7.0, 10.0, 2.0, 5.0, 8.0, 11.0, 3.0, 6.0, 9.0, 12.0 ] );
* var work = new Float64Array( 3 );
*
* var out = dlange( 'F', 3, 4, A, 4, 1, 0, work, 1, 0 );
* // returns ~25.5
*/
function dlange( norm, M, N, A, strideA1, strideA2, offsetA, work, strideWork, offsetWork ) { // eslint-disable-line max-len
	var value;
	var temp;
	var sum;
	var out;
	var i;
	var j;

	if ( min( M, N ) === 0 ) {
		value = 0.0;
	}

	else if ( norm === 'M' ) {
		value = 0.0;
		for ( i = 0; i < M; i++ ) {
			for ( j = 0; j < N; j++ ) {
				temp = A[ offsetA + (i*strideA1) + (j*strideA2) ];
				if ( value < temp || isnan( temp ) ) {
					value = temp;
				}
			}
		}
	}

	else if ( norm === 'O' ) {
		value = 0;
		for ( j = 0; j < N; j++ ) {
			sum = 0;
			for ( i = 0; i < M; i++ ) {
				sum += abs( A[ offsetA + (i*strideA1) + (j*strideA2) ] );
			}
			if ( value < sum || isnan( sum ) ) {
				value = sum;
			}
		}
	}

	else if ( norm === 'I' ) {
		for ( i = 0; i < M; i++ ) {
			work[ offsetWork + (i*strideWork) ] = 0.0;
		}

		for ( j = 0; j < N; j++ ) {
			for ( i = 0; i < M; i++ ) {
				work[ offsetWork + (i*strideWork) ] += abs( A[ offsetA + (i*strideA1) + (j*strideA2) ] ); // eslint-disable-line max-len
			}
		}

		value = 0;

		for ( i = 0; i < M; i++ ) {
			temp = work[ offsetWork + (i*strideWork) ];
			if ( value < temp || isnan( temp ) ) {
				value = temp;
			}
		}
	}

	else if ( norm === 'F' ) {
		out = new Float64Array( [ 0.0, 1.0 ] );
		for ( i = 0; i < N; i++ ) {
			dlassq( M, A, strideA1, offsetA + (i*strideA2), out[ 0 ], out[ 1 ], out, 1, 0 ); // eslint-disable-line max-len
		}
		value = out[ 0 ] * sqrt( out[ 1 ] );
	}

	return value;
}


// EXPORTS //

module.exports = dlange;
